package com.xiaojingyu.furniture;

import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

import com.xiaojingyu.XiaojingyuMod;
import com.xiaojingyu.furniture.FurnitureSpec.Cell;
import com.xiaojingyu.furniture.FurnitureSpec.Collide;

/**
 * The furniture of rounds 2 and 3 (docs/FURNITURE.md §8.2, §9.1), read from {@link FurnitureShapes#KINDS} (generated by
 * furn's web/tools/furn-mc.mjs export): size, boxes per part, collide per part, light. Order = the
 * creative tab. Models that reach out of their cells (round 3: the parasol's canopy, the hanging basket's arm)
 * need nothing here: the generator already keeps their boxes and outlines inside each cell (0..16).
 */
public final class FurnitureSpecs {
    private static final Map<String, FurnitureSpec> BY_ID = new LinkedHashMap<>();

    static {
        for (FurnitureShapes.Kind k : FurnitureShapes.KINDS) {
            Cell[] cells = new Cell[k.parts()];
            for (int p = 0; p < cells.length; p++) {
                cells[p] = new Cell(k.outlines[p], k.boxes[p], collide(k, p), k.light);
            }
            BY_ID.put(k.id, new FurnitureSpec(k.id, k.w, k.d, k.h, cells));
        }
    }

    private FurnitureSpecs() {
    }

    private static Collide collide(FurnitureShapes.Kind k, int part) {
        return switch (k.collide[part]) {
            case "box" -> Collide.BOX;
            case "thin" -> Collide.THIN;
            case "none" -> Collide.NONE;
            default -> {
                XiaojingyuMod.LOGGER.warn("[xiaojingyu] furniture {} part {}: unknown collide '{}', using box", k.id, part, k.collide[part]);
                yield Collide.BOX;
            }
        };
    }

    /** All kinds of rounds 2 and 3, in creative-tab order. */
    public static List<FurnitureSpec> all() {
        return List.copyOf(BY_ID.values());
    }

    /** One kind by block path ("sofa" or "xiaojingyu:sofa"); throws if unknown. */
    public static FurnitureSpec get(String id) {
        String key = id.startsWith("xiaojingyu:") ? id.substring("xiaojingyu:".length()) : id;
        FurnitureSpec spec = BY_ID.get(key);
        if (spec == null) {
            throw new IllegalArgumentException("unknown furniture " + id);
        }
        return spec;
    }
}
